def grep(pattern, flags, files):
    flag_set = set(flags.split())
    invert = "-v" in flag_set
    whole_line = "-x" in flag_set
    ignore_case = "-i" in flag_set
    line_numbers = "-n" in flag_set
    file_names_only = "-l" in flag_set
    multiple_files = len(files) > 1

    results = []
    for filename in files:
        with open(filename) as file:
            lines = file.readlines()
        file_has_match = False
        for line_number, line in enumerate(lines, start=1):
            line_text = line.rstrip("\n")
            if ignore_case:
                haystack = line_text.lower()
                needle = pattern.lower()
            else:
                haystack = line_text
                needle = pattern
            matched = haystack == needle if whole_line else needle in haystack
            if matched != invert:
                file_has_match = True
                if file_names_only:
                    continue
                prefix = ""
                if multiple_files:
                    prefix += filename + ":"
                if line_numbers:
                    prefix += str(line_number) + ":"
                results.append(prefix + line_text + "\n")
        if file_names_only and file_has_match:
            results.append(filename + "\n")
    return "".join(results)
